@Test
public void test() {
    final Command a = new Command("a client id", "a field id", null, null, "a execute", null, "a conf", null, new Collapse(Collapse.Operation.show, "a collapse"), false);
    final Command b = new Command("b client id", "b field id", null, null, "b execute", null, "b conf", null, new Collapse(Collapse.Operation.show, "b collapse"), false);
    a.merge(b);
    Assertions.assertEquals(("{'click':" + "{'clientId':'a client id'," + "'fieldId':'a field id'," + "'execute':'a execute b execute'" + ",'collapse':{'transition':'show','forId':'a collapse'}" + ",'confirmation':'a conf'}}").replaceAll("'", "\""), JsonUtils.encode(new CommandMap(a)));
    final Command c = new Command(null, null, null, null, null, null, null, null, null, false);
    c.merge(b);
    Assertions.assertEquals(("{'click':" + "{'clientId':'b client id'," + "'fieldId':'b field id'," + "'execute':'b execute'," + "'collapse':{'transition':'show','forId':'b collapse'}," + "'confirmation':'b conf'}}").replaceAll("'", "\""), JsonUtils.encode(new CommandMap(c)));
}

