    Assertions.assertEquals("controller.viewDetails", AuthorizationHelper.skipParameterPart("controller.viewDetails(cc.attrs.value, facesContext)"));
    Assertions.assertEquals("x", AuthorizationHelper.skipParameterPart("x"));
    Assertions.assertEquals("", AuthorizationHelper.skipParameterPart(""));
    Assertions.assertEquals("#{x.a}", AuthorizationHelper.skipParameterPart("#{x.a()}"));
    Assertions.assertEquals("#{x.a)(}", AuthorizationHelper.skipParameterPart("#{x.a)(}"));
    Assertions.assertEquals("#{x.a)}", AuthorizationHelper.skipParameterPart("#{x.a)}"));
    Assertions.assertEquals("#{x.a(}", AuthorizationHelper.skipParameterPart("#{x.a(}"));
}

